import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"For Agents","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents.md","filePath":"ai/agents.md","lastUpdated":1792596430000}`),a={name:`ai/agents.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="for-agents" tabindex="-1">For Agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to “For Agents”">​</a></h1><p>给 Claude Code、Cursor、Codex、GitHub Copilot 这类 AI 编程工具的入口：在项目里用表单设计器时，怎样让 AI 写对接法；参与表单仓库开发时，AI 该读什么。</p><p>表单设计器没有单独的命令行或 MCP 服务端，AI 工具要的资料在两处：本站构建时产出的<a href="./llms">机读文档</a>，以及仓库根的 <code>AGENTS.md</code>。表单用到的 XiHan.UI 另有自己的 <a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">AI 辅助开发</a>资料。</p><h2 id="复制这段提示词" tabindex="-1">复制这段提示词 <a class="header-anchor" href="#复制这段提示词" aria-label="Permalink to “复制这段提示词”">​</a></h2><p>把下面这段放进对话，或写进项目的 <code>AGENTS.md</code> / <code>CLAUDE.md</code> / <code>.cursor/rules</code>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个项目用曦寒表单设计器（@xihan-form/*）设计表单模板、按模板渲染表单并校验提交的数据。</span></span>
<span class="line"><span>写代码前先读 https://form.docs.xihanfun.com/llms.txt，按需读取其中列出的页面（站点地址后加 .md 取 Markdown）。</span></span>
<span class="line"><span>元素、属性、事件、模板结构、种类与问题码以文档和项目里装的版本为准，不要凭记忆写，也不要套用别的表单组件的 API。</span></span>
<span class="line"><span>用到 XiHan.UI 的组件、设计令牌或语言包时，再读 https://ui.docs.xihanfun.com/llms.txt。</span></span></code></pre></div><h2 id="要装的包" tabindex="-1">要装的包 <a class="header-anchor" href="#要装的包" aria-label="Permalink to “要装的包”">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>安装</th><th>注册</th><th>引入的样式</th></tr></thead><tbody><tr><td>业务页面填表</td><td><code>pnpm add @xihan-form/runtime @xihan-ui/web-components @xihan-ui/styles</code></td><td><code>defineFormRenderer()</code></td><td><code>@xihan-ui/styles/index.css</code>、<code>@xihan-form/runtime/style.css</code></td></tr><tr><td>设计模板</td><td><code>pnpm add @xihan-form/designer @xihan-form/runtime @xihan-ui/styles @xihan-ui/designer-shell</code></td><td><code>defineFormDesigner()</code></td><td>上面两份，再加 <code>@xihan-ui/designer-shell/style.css</code>、<code>@xihan-form/designer/style.css</code></td></tr><tr><td>服务端或脚本里复核</td><td><code>pnpm add @xihan-form/core</code></td><td>—</td><td>—</td></tr></tbody></table><p><code>@xihan-form/runtime</code> 会带上 <code>@xihan-form/core</code>。代码里要 import <code>@xihan-form/core</code>（模板类型 <code>FormDocument</code>、<code>validateDocument</code>、<code>validateValues</code> 等）时，也把它写进项目的依赖。<code>@xihan-ui/*</code> 是表单各包的 peer 依赖，由项目装唯一的一份，与项目自己用的 XiHan.UI 同一个版本，页面上不会出现两份 UI；代码里直接 import 的 <code>@xihan-ui/*</code>（如设置界面语言用的 <code>@xihan-ui/web-components</code>）同样写进项目的依赖。</p><h2 id="关键约定" tabindex="-1">关键约定 <a class="header-anchor" href="#关键约定" aria-label="Permalink to “关键约定”">​</a></h2><p>把这几条一并告诉 AI，常见的错写多出在这里：</p><ul><li><strong>先注册再用</strong>：元素不在 import 时注册，应用启动时调用一次 <code>defineFormRenderer()</code> 或 <code>defineFormDesigner()</code>，重复调用不报错；<code>defineFormDesigner()</code> 已经包含渲染器。</li><li><strong>对象走属性</strong>：模板、数据、扩展与回调这类对象交给元素的属性（如 <code>schema</code>、<code>values</code>、<code>extensions</code>、<code>loadOptions</code>、<code>uploadFile</code>），不写成 attribute。Vue 里用 <code>.prop</code> 修饰，并把 <code>xh-</code> 开头的标签声明为自定义元素，见<a href="./../guide/host#在前端框架里使用">在前端框架里使用</a>。</li><li><strong>模板是纯 JSON</strong>：模板是一份 <code>FormDocument</code>，不含函数与脚本；字段的 <code>key</code> 是表单数据的键，校验与联动的条件、取值写成受限表达式。保存前用设计器的 <code>validate()</code> 或 core 的 <code>validateDocument</code> 检查，问题码见<a href="./../reference/issues">问题码</a>。</li><li><strong>宿主管保存、取数与权限</strong>：组件不发网络请求。设计器每次修改派发 <code>schema-change</code>，保存命令派发 <code>save</code>，宿主存好后调用 <code>markSaved()</code>；渲染器的选项与附件经 <code>loadOptions</code>、<code>uploadFile</code> 回调，校验通过派发 <code>submit</code>、没通过派发 <code>invalid</code>。服务端用 <code>resolveLinkage</code> 求出联动状态后再交给 <code>validateValues</code> 复核，见<a href="./../guide/host">与宿主集成</a>。</li><li><strong>扩展走 <code>extensions</code></strong>：种类、渲染方式、属性编辑器、模板规则、命令与面板都经 <code>extensions</code> 登记，只对这一个实例生效，不改包内源码，见<a href="./../guide/extensions">扩展</a>。</li><li><strong>语言包合并后全局设置</strong>：界面文字缺省是英文。语言包在 <code>@xihan-form/runtime/locale</code>，名字是 <code>form</code> 加 XiHan.UI 语言包的名字（<code>zhCN</code> 对 <code>formZhCN</code>），与 UI 同一语言的那份合并：<code>setXhConfig(mergeXhConfig(zhCN, formZhCN))</code>，见<a href="./../quickstart#界面语言">快速开始</a>。</li></ul><h2 id="参与表单仓库开发" tabindex="-1">参与表单仓库开发 <a class="header-anchor" href="#参与表单仓库开发" aria-label="Permalink to “参与表单仓库开发”">​</a></h2><p>仓库根的 <code>AGENTS.md</code> 是写给 AI 的仓库规范：</p><table tabindex="0"><thead><tr><th>内容</th><th>说明</th></tr></thead><tbody><tr><td>仓库概览与目录结构</td><td><code>form/</code> 是三个包与开发预览页的工作区，<code>docs/</code> 是本站</td></tr><tr><td>常用命令</td><td>构建、类型检查、单测、Lint、产物契约与冒烟，以及文档站的命令</td></tr><tr><td>文档站</td><td>参考页由源码生成、不手改，正文的示例放在 <code>examples/</code> 并经类型检查与模板自检</td></tr><tr><td>分层与依赖</td><td><code>designer → runtime → core</code>，core 不碰 DOM，运行时依赖只允许 <code>@xihan-form/*</code> 与 <code>@xihan-ui/*</code></td></tr><tr><td>硬性约定</td><td>模板即数据、无全局状态、数据由使用方提供、对外契约、命名与语言包、样式、注释</td></tr><tr><td>发版、分支、Git 与提交</td><td>各自的做法与禁止事项</td></tr></tbody></table><p><code>CLAUDE.md</code> 是指向 <code>AGENTS.md</code> 的链接，Claude Code 打开仓库即读到；Codex 直接读 <code>AGENTS.md</code>；Cursor、GitHub Copilot 等工具在各自的规则文件里写一句「先读仓库根的 AGENTS.md」即可。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./llms">LLMs.txt</a> · <a href="./../quickstart">快速开始</a> · <a href="./../guide/host">与宿主集成</a></li><li><a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.UI 的 AI 辅助开发</a></li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};